<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { Activity, ChevronDown, KeyRound, Pause, Play, Plus, RotateCcw, X as Square } from 'lucide-vue-next'
import { api } from '../api'
import { formatSize } from '../format'
import type { BackgroundTask } from '../types'
import DownloadCreateDialog from './DownloadCreateDialog.vue'
import StatusBadge from './StatusBadge.vue'

const props=withDefaults(defineProps<{tasks:BackgroundTask[];parentId:string;hideTrigger?:boolean}>(),{hideTrigger:false})
const emit=defineEmits<{changed:[];cancel:[task:BackgroundTask];retry:[task:BackgroundTask]}>()
const center=ref<HTMLDetailsElement|null>(null)
const download=ref<InstanceType<typeof DownloadCreateDialog>|null>(null)
const passwordTask=ref<BackgroundTask|null>(null)
const password=ref('')
const error=ref('')
const showAllCompleted=ref(false)
const active=computed(()=>props.tasks.filter(t=>['running','queued','retrying','waiting_input'].includes(t.status)))
const completed=computed(()=>props.tasks.filter(t=>['completed','cancelled'].includes(t.status)))
const failed=computed(()=>props.tasks.filter(t=>t.status==='failed'))
const visibleCompleted=computed(()=>showAllCompleted.value?completed.value:completed.value.slice(0,4))
const progress=computed(()=>active.value.length?Math.round(active.value.reduce((n,t)=>n+t.progress,0)/active.value.length):0)
const labels:Record<string,string>={upload:'上传',bt:'BT 下载',url_download:'直链下载',archive_extract:'解压',audio_merge:'音频合并',video_hls:'视频 HLS',audio_hls:'音频 HLS',video_fmp4:'视频转换',subtitle:'字幕处理'}
const status=(task:BackgroundTask)=>task.status==='waiting_input'?(task.type==='archive_extract'?'等待输入密码':'等待输入'):task.status==='retrying'?'等待重试':task.status==='queued'?'排队中':task.status==='running'?task.phase:task.status==='completed'?'已完成':task.status==='cancelled'?'已取消':task.error||'失败'
function closeCenter(){if(center.value)center.value.open=false}
function openCenter(){if(center.value)center.value.open=true}
function openDownload(){closeCenter();download.value?.openCreate()}
function openTask(task:BackgroundTask){if(task.type==='bt'&&['metadata','waiting'].includes(task.phase)){closeCenter();download.value?.openById(task.source_id||task.id)}else if(task.status==='waiting_input'&&task.type==='archive_extract'){closeCenter();passwordTask.value=task;password.value='';error.value=''}}
async function submitPassword(){if(!passwordTask.value||!password.value)return;try{await api(`/api/tasks/${passwordTask.value.id}/input`,{method:'POST',body:JSON.stringify({password:password.value})});passwordTask.value=null;password.value='';emit('changed')}catch(e){error.value=(e as Error).message}}
async function clearFinished(){await Promise.all(completed.value.map(task=>api(`/api/tasks/${task.id}`,{method:'DELETE'}).catch(()=>undefined)));emit('changed')}
async function downloadAction(task:BackgroundTask,action:'pause'|'resume'){try{await api(`/api/downloads/${task.source_id}/${action}`,{method:'POST'});emit('changed')}catch(e){error.value=(e as Error).message}}
function closeFromOutside(event:PointerEvent){const target=event.target;if(center.value?.open&&target instanceof Node&&!center.value.contains(target))closeCenter()}
function closeFromEscape(event:KeyboardEvent){if(event.key!=='Escape')return;if(passwordTask.value){passwordTask.value=null;return}if(center.value?.open){closeCenter();center.value.querySelector<HTMLElement>('summary')?.focus()}}
onMounted(()=>{document.addEventListener('pointerdown',closeFromOutside);document.addEventListener('keydown',closeFromEscape)})
onBeforeUnmount(()=>{document.removeEventListener('pointerdown',closeFromOutside);document.removeEventListener('keydown',closeFromEscape)})
defineExpose({openCenter,closeCenter})
</script>

<template>
  <details ref="center" class="task-center">
    <summary v-show="!hideTrigger" title="任务中心"><Activity/><span v-if="active.length">{{ active.length }}</span></summary>
    <section class="task-panel">
      <header><div><strong>任务中心</strong><small>{{ active.length?`${active.length} 项进行中 · ${progress}%`:'任务通知' }}</small></div><StatusBadge v-if="failed.length" tone="danger">{{ failed.length }} 项失败</StatusBadge><StatusBadge v-else-if="active.length" tone="info">{{ active.length }} 项活动</StatusBadge><StatusBadge v-else tone="success">已就绪</StatusBadge><button @click.prevent.stop="openDownload"><Plus/>新建下载</button></header>
      <p v-if="!tasks.length" class="empty">还没有后台任务</p>
      <div v-else class="task-list">
        <section v-if="active.length" class="task-group active-group"><h3>进行中 <span>{{ active.length }}</span></h3><article v-for="task in active" :key="task.id" @click="openTask(task)"><span class="kind">{{ labels[task.type]||task.type }}</span><div><strong :title="task.name">{{ task.name||labels[task.type]||task.id }}</strong><small>{{ status(task) }}<template v-if="task.speed"> · {{ formatSize(task.speed) }}/s</template></small><i><b :class="task.status" :style="{width:`${task.progress}%`}"></b></i></div><em>{{ Math.round(task.progress) }}%</em><span class="actions"><button v-if="['bt','url_download'].includes(task.type)&&['queued','downloading'].includes(task.phase)" title="暂停" @click.stop="downloadAction(task,'pause')"><Pause/></button><button v-else-if="['bt','url_download'].includes(task.type)&&task.phase==='paused'" title="继续" @click.stop="downloadAction(task,'resume')"><Play/></button><button title="取消" @click.stop="$emit('cancel',task)"><Square/></button><button v-if="task.status==='waiting_input'&&task.type==='archive_extract'" title="输入密码" @click.stop="openTask(task)"><KeyRound/></button></span></article></section>
        <section v-if="completed.length" class="task-group completed-group"><h3>最近完成 <span>{{ completed.length }}</span><button class="clear-completed" @click="clearFinished">清除完成</button></h3><article v-for="task in visibleCompleted" :key="task.id"><span class="kind">{{ labels[task.type]||task.type }}</span><div><strong :title="task.name">{{ task.name||labels[task.type]||task.id }}</strong><small>{{ status(task) }}</small><i><b class="completed" style="width:100%"></b></i></div><em>100%</em></article><button v-if="completed.length>4" class="expand" @click="showAllCompleted=!showAllCompleted"><span>{{ showAllCompleted?'收起':`展开其余 ${completed.length-4} 项` }}</span><ChevronDown :class="{up:showAllCompleted}" aria-hidden="true" /></button></section>
        <section v-if="failed.length" class="task-group failed-group"><h3>失败 <span>{{ failed.length }}</span></h3><article v-for="task in failed" :key="task.id"><span class="kind">{{ labels[task.type]||task.type }}</span><div><strong :title="task.name">{{ task.name||labels[task.type]||task.id }}</strong><small>{{ status(task) }}</small><i><b class="failed" style="width:100%"></b></i></div><em>失败</em><span class="actions"><button v-if="task.retry_count<task.max_retries" title="重试" @click.stop="$emit('retry',task)"><RotateCcw/></button></span></article></section>
      </div>
      <p v-if="error" class="error">{{ error }}</p>
    </section>
  </details>
  <DownloadCreateDialog ref="download" :parent-id="parentId" @changed="$emit('changed')" />
  <Teleport to="body"><div v-if="passwordTask" class="input-backdrop" @pointerdown.self="passwordTask=null"><form class="input-dialog" @pointerdown.stop @submit.prevent="submitPassword"><strong>输入压缩包密码</strong><small>{{ passwordTask.name }}</small><input v-model="password" type="password" maxlength="1024" autofocus><p v-if="error">{{ error }}</p><footer><button type="button" @click="passwordTask=null">取消</button><button :disabled="!password">继续任务</button></footer></form></div></Teleport>
</template>

<style scoped>
.task-center{position:relative}.task-center>summary{position:relative;display:grid;place-items:center;width:44px;height:44px;border-radius:50%;cursor:pointer;list-style:none}.task-center>summary::-webkit-details-marker{display:none}.task-center>summary:hover{background:#f1f5f9}.task-center>summary svg{width:21px;color:#3d5f7e}.task-center>summary span{position:absolute;right:-2px;top:-1px;display:grid;place-items:center;min-width:17px;height:17px;padding:0 4px;border:2px solid #fff;border-radius:9px;background:#2563eb;color:#fff;font-size:9px;font-weight:800}.task-panel{position:absolute;z-index:45;top:52px;right:-12px;display:flex;width:min(470px,calc(100vw - 24px));max-height:min(70vh,640px);flex-direction:column;overflow:hidden;border:1px solid #dfe6ee;border-radius:17px;background:#fff;box-shadow:0 24px 70px #0f172a2e}.task-panel>header{display:flex;min-height:62px;flex:0 0 auto;align-items:center;justify-content:space-between;padding:0 17px;border-bottom:1px solid #edf1f5;background:#fff}.task-panel>header div{display:flex;flex-direction:column}.task-panel>header small{color:#94a3b8;font-size:10px}.task-panel>header button{display:flex;align-items:center;gap:4px;padding:7px 10px;border:0;border-radius:9px;background:#e0f2fe;color:#0369a1;font-weight:700}.task-panel>header svg{width:14px}.task-list{min-height:0;overflow:auto;overscroll-behavior:contain;padding:6px 0}.task-group h3{display:flex;align-items:center;gap:6px;margin:0;padding:11px 14px 7px;color:#52657b;font-size:11px}.task-group h3 span{display:grid;min-width:18px;height:18px;place-items:center;border-radius:9px;background:#e8f1fb;color:#2467ae;font-size:9px}.task-group h3 button{margin-left:auto;padding:3px 7px;border:0;background:transparent;color:#2563eb;font-size:10px}.task-list article{display:grid;grid-template-columns:70px minmax(0,1fr) auto auto;align-items:center;gap:9px;margin:3px 8px;padding:12px 10px;border:1px solid #e8eef5;border-radius:11px;background:#fff;cursor:default}.active-group article{border-color:#d8e8f8;box-shadow:0 4px 13px #2563eb0b}.completed-group article{background:#fafcfd;opacity:.82}.failed-group article{border-color:#fecaca;background:#fff8f8;box-shadow:0 3px 12px #dc262610}.failed-group h3{color:#b91c1c}.kind{color:#2563eb;font-size:10px;font-weight:750}.task-list article>div{display:flex;min-width:0;flex-direction:column;gap:4px}.task-list strong,.task-list small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.task-list strong{font-size:12px}.task-list small{color:#8795a8;font-size:10px}.task-list i{height:3px;overflow:hidden;border-radius:3px;background:#e8edf3}.task-list i b{display:block;height:100%;background:#3b82f6}.task-list i b.completed{background:#22c55e}.task-list i b.failed{background:#ef4444}.task-list em{color:#64748b;font-size:10px;font-style:normal}.failed-group em{color:#dc2626;font-weight:700}.actions{display:flex}.actions button{border:0;background:transparent;color:#64748b}.actions button[title="取消"]{display:grid;width:28px;height:28px;place-items:center;padding:0;border-radius:8px;color:#dc3a4c;transition:background-color .15s ease,color .15s ease,transform .15s ease}.actions button[title="取消"]:hover{background:#feecef;color:#b91c2f;transform:scale(1.06)}.actions button[title="取消"]:focus-visible{outline:2px solid #fda4af;outline-offset:1px}.actions button[title="取消"] svg{width:16px;height:16px;stroke-width:2.2}.actions svg{width:15px}.expand{display:block;margin:5px auto 8px;padding:6px 12px;border:0;border-radius:8px;background:#f1f5f9;color:#52657b;font-size:10px}.empty,.error{padding:25px;text-align:center;color:#94a3b8}.error{color:#b91c1c}.input-backdrop{position:fixed;z-index:140;inset:0;display:grid;place-items:center;background:#0f172a80}.input-dialog{display:flex;width:min(400px,calc(100vw - 30px));flex-direction:column;gap:10px;padding:22px;border-radius:18px;background:#fff}.input-dialog small{color:#64748b}.input-dialog input{padding:11px;border:1px solid #d8e1ea;border-radius:9px}.input-dialog p{color:#b91c1c}.input-dialog footer{display:flex;justify-content:flex-end;gap:8px}.input-dialog button{padding:8px 12px;border-radius:9px;border:1px solid #d8e1ea;background:#fff}.input-dialog button:last-child{border:0;background:#1677b8;color:#fff}@media(max-width:850px){.task-panel{position:fixed;top:calc(66px + env(safe-area-inset-top,0px));right:max(10px,env(safe-area-inset-right,0px));bottom:max(10px,env(safe-area-inset-bottom,0px));width:calc(100vw - 20px - env(safe-area-inset-left,0px) - env(safe-area-inset-right,0px));max-height:min(70vh,640px)}.task-list article{grid-template-columns:62px minmax(0,1fr) auto}}
.task-panel{z-index:25;isolation:isolate;background:#fff}.task-list{background:#fff}.task-group h3 .clear-completed{min-height:38px;margin-left:auto;padding:0 11px;border:1px solid transparent;border-radius:9px;background:transparent;color:#2563eb;font-size:11px;font-weight:700}.task-group h3 .clear-completed:hover{border-color:#dbeafe;background:#eff6ff}.task-group h3 .clear-completed:focus-visible{outline:2px solid #60a5fa;outline-offset:1px}.completed-group>.expand{display:flex;width:calc(100% - 16px);min-height:40px;align-items:center;justify-content:center;margin:7px 8px 10px;padding:0 14px;border:1px solid #dbe6f2;border-radius:10px;background:#f6f9fc;color:#3d5f7e;font-size:11px;font-weight:700;gap:7px}.completed-group>.expand:hover{border-color:#bfdbfe;background:#eff6ff;color:#2563eb}.completed-group>.expand:focus-visible{outline:2px solid #60a5fa;outline-offset:1px}.completed-group>.expand svg{width:15px;height:15px;transition:transform .18s}.completed-group>.expand svg.up{transform:rotate(180deg)}
</style>
